79	 /// The terminal frame [`Runner::run_streamed`] synthesizes when a run ends
80	 /// without one of its own, or `None` when the run succeeded.
81	 ///
82	 /// Cancellation and timeout render through [`RunInterrupt::terminal_event`],
83	 /// **not** through [`RunError`]'s `Display`. The two disagree — `RunError::Cancelled`
84	 /// displays as `"cancelled"` while the canonical synthesized frame says
85	 /// `"run cancelled"` — so going through `Display` here would make this runner emit
86	@@ -315,20 +299,46 @@ fn synthetic_terminal_event(result: &Result<RunResult, RunError>) -> Option<Agen
87	 /// terminal. It tests for *any* terminal via [`AgentEvent::is_terminal`], not
88	 /// just `RunFailed`.
89	 fn append_synthetic_terminal(events: &mut Vec<AgentEvent>, event: Option<AgentEvent>) {
90	     if let Some(event) = event {
91	         if !events.last().is_some_and(AgentEvent::is_terminal) {
92	             events.push(event);
93	         }
94	     }
95	 }
