97	+/// Assemble the durable run's `(events, result)` into the handle
98	+/// [`Runner::run_streamed`] returns. Pure, so the whole assembly is unit-tested
99	+/// without a Temporal server (SMA-516).
100	+fn into_streaming(
101	+    mut events: Vec<AgentEvent>,
102	+    result: Result<RunResult, RunError>,
103	+) -> RunResultStreaming {
104	+    let failure = FailureSlot::new();
105	+    let terminal = synthetic_terminal_event(&result);
106	+    // Move the structured error into the slot only for an agent failure;
107	+    // the event itself was already rendered above.
108	+    if let Err(RunError::Agent(err)) = result {
109	+        failure.set(err);
110	+    }
111	+
112	+    // `collect()` only reads the failure slot once it observes a terminal
113	+    // `RunFailed` in the stream. The durable event log already carries one
114	+    // for `AgentFailed` runs; synthesize one for the terminal states that do
115	+    // not (cancellation/timeout/infra), so a failed run never collects as
116	+    // `Ok`. `append_synthetic_terminal` owns the guard that stops this from
117	+    // appending a *second* terminal (SMA-422).
118	+    append_synthetic_terminal(&mut events, terminal);
119	+
120	+    RunResultStreaming::with_failure(stream::iter(events).boxed(), failure)
121	+}
